declare_lint ! { # [doc = " The `uses_power_alignment` lint detects specific `repr(C)`"] # [doc = " aggregates on AIX."] # [doc = " In its platform C ABI, AIX uses the \"power\" (as in PowerPC) alignment"] # [doc = " rule (detailed in https://www.ibm.com/docs/en/xl-c-and-cpp-aix/16.1?topic=data-using-alignment-modes#alignment),"] # [doc = " which can also be set for XLC by `#pragma align(power)` or"] # [doc = " `-qalign=power`. Aggregates with a floating-point type as the"] # [doc = " recursively first field (as in \"at offset 0\") modify the layout of"] # [doc = " *subsequent* fields of the associated structs to use an alignment value"] # [doc = " where the floating-point type is aligned on a 4-byte boundary."] # [doc = ""] # [doc = " Effectively, subsequent floating-point fields act as-if they are `repr(packed(4))`. This"] # [doc = " would be unsound to do in a `repr(C)` type without all the restrictions that come with"] # [doc = " `repr(packed)`. Rust instead chooses a layout that maintains soundness of Rust code, at the"] # [doc = " expense of incompatibility with C code."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (fails on non-powerpc64-ibm-aix)"] # [doc = " #[repr(C)]"] # [doc = " pub struct Floats {"] # [doc = "     a: f64,"] # [doc = "     b: u8,"] # [doc = "     c: f64,"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " warning: repr(C) does not follow the power alignment rule. This may affect platform C ABI compatibility for this type"] # [doc = "  --> <source>:5:3"] # [doc = "   |"] # [doc = " 5 |   c: f64,"] # [doc = "   |   ^^^^^^"] # [doc = "   |"] # [doc = "   = note: `#[warn(uses_power_alignment)]` on by default"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The power alignment rule specifies that the above struct has the"] # [doc = " following alignment:"] # [doc = "  - offset_of!(Floats, a) == 0"] # [doc = "  - offset_of!(Floats, b) == 8"] # [doc = "  - offset_of!(Floats, c) == 12"] # [doc = ""] # [doc = " However, Rust currently aligns `c` at `offset_of!(Floats, c) == 16`."] # [doc = " Using offset 12 would be unsound since `f64` generally must be 8-aligned on this target."] # [doc = " Thus, a warning is produced for the above struct."] USES_POWER_ALIGNMENT , Warn , "Structs do not follow the power alignment rule under repr(C)" }